#include <iostream>
#include <utility>
#include <vector>

class Tracer
{
public:
    Tracer() : m_id{ ++s_next } { std::cout << "[#" << m_id << "] default ctor\n"; }
    Tracer(const Tracer& other) : m_id{ ++s_next } { std::cout << "[#" << m_id << "] copy ctor from #" << other.m_id << '\n'; }
    // TODO: move constructor, copy assignment, move assignment
    ~Tracer() { std::cout << "[#" << m_id << "] destructor\n"; }

private:
    static inline int s_next{ 0 };
    int m_id{};
};

void byValue(Tracer t) {}

int main()
{
    std::cout << "--- pass by value ---\n";
    // Prediction: one copy constructor, then its destructor when byValue returns.
    Tracer a{};
    byValue(a);

